DROP PROCEDURE IF EXISTS `ms_ranked_cache_restore_20261007`;
DELIMITER $$
CREATE PROCEDURE `ms_ranked_cache_restore_20261007`()
BEGIN
    DECLARE `dungeon_1_10` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_11_20` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_21_30` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_31_40` INT UNSIGNED DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `information_schema`.`TABLES`
        WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` IN ('item_loot_template', 'reference_loot_template')
            AND `ENGINE` = 'InnoDB') <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: InnoDB loot tables required';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM `tmp_ms_ranked_candidate`) <> 24439 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: expected 24439 candidate assignments';
    END IF;
    -- One scan: MySQL cannot reopen a temporary table twice in one statement.
    SELECT COUNT(CASE WHEN `Pool` = 9003801 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003802 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003803 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003804 THEN 1 END)
    INTO `dungeon_1_10`, `dungeon_11_20`,
        `dungeon_21_30`, `dungeon_31_40`
    FROM `tmp_ms_ranked_candidate`;
    IF `dungeon_1_10` <> 6109 OR `dungeon_11_20` <> 6110
        OR `dungeon_21_30` <> 6110 OR `dungeon_31_40` <> 6110 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: candidate family count mismatch';
    END IF;
    IF (SELECT COUNT(*) FROM `item_template`
        WHERE `entry` IN (1278059, 1278064, 1278073, 1278082) AND (`Flags` & 4) <> 0 AND `ScriptName` = '') <> 4 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: missing scriptless HAS_LOOT containers';
    END IF;
    IF EXISTS (
        SELECT 1 FROM `tmp_ms_ranked_candidate` AS `c`
        LEFT JOIN `item_template` AS `i` ON `i`.`entry` = `c`.`Item`
        WHERE `i`.`entry` IS NULL OR BINARY `i`.`name` <> BINARY `c`.`Name`
            OR `i`.`class` <> `c`.`Class` OR `i`.`subclass` <> `c`.`Subclass`
            OR `i`.`InventoryType` <> `c`.`InventoryType` OR `i`.`Quality` <> `c`.`Quality`
            OR `i`.`RequiredLevel` <> `c`.`RequiredLevel` OR `i`.`displayid` <> `c`.`DisplayId`
            OR `i`.`ItemLevel` <> `c`.`ItemLevel`
            OR BINARY `i`.`description` <> BINARY `c`.`Description`
            OR `i`.`RequiredLevel` > 60 OR `i`.`class` NOT IN (2, 4) OR `i`.`InventoryType` = 0
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: candidate metadata mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM `reference_loot_template`
        WHERE `Entry` IN (9003801, 9003802, 9003803, 9003804)
            AND `Comment` <> 'MS Classic ranked dungeon cache pool')
        OR EXISTS (SELECT 1 FROM `reference_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `item_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804)
                AND `Entry` NOT IN (1278059, 1278064, 1278073, 1278082)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: reserved reference namespace collision';
    END IF;
    IF EXISTS (SELECT 1 FROM `creature_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `disenchant_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `fishing_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `gameobject_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `mail_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `milling_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `pickpocketing_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `prospecting_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `skinning_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `spell_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804))
        OR EXISTS (SELECT 1 FROM `player_loot_template`
            WHERE ABS(`Reference`) IN (9003801, 9003802, 9003803, 9003804)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: references used by another loot store';
    END IF;
    IF EXISTS (SELECT 1 FROM `conditions`
        WHERE (`SourceTypeOrReferenceId` = 10
            AND `SourceGroup` IN (9003801,9003802,9003803,9003804))
            OR (`SourceTypeOrReferenceId` = 5 AND `SourceGroup` IN (1278059,1278064,1278073,1278082))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: existing loot conditions require review';
    END IF;
    DELETE FROM `reference_loot_template`
    WHERE `Entry` IN (9003801, 9003802, 9003803, 9003804);
    INSERT INTO `reference_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    SELECT `Pool`, `Item`, 0, 0, 0, 1, 1, 1, 1, 'MS Classic ranked dungeon cache pool'
    FROM `tmp_ms_ranked_candidate`;
    DELETE FROM `item_loot_template` WHERE `Entry` IN (1278059, 1278064, 1278073, 1278082);
    INSERT INTO `item_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    VALUES
    (1278059, 1, 9003801, 100, 0, 1, 1, 1, 1, 'MS ranked: one Mythic 1-10 Dungeon item'),
    (1278064, 1, 9003802, 100, 0, 1, 1, 1, 1, 'MS ranked: one Mythic 11-20 Dungeon item'),
    (1278073, 1, 9003803, 100, 0, 1, 1, 1, 1, 'MS ranked: one Mythic 21-30 Dungeon item'),
    (1278082, 1, 9003804, 100, 0, 1, 1, 1, 1, 'MS ranked: one Mythic 31-40 Dungeon item');
    IF (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278059) <> 1
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278064) <> 1
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278073) <> 1
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278082) <> 1
        OR (SELECT COUNT(*) FROM `reference_loot_template`
            WHERE `Entry` IN (9003801,9003802,9003803,9003804)) <> 24439 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ranked caches: post-write row count mismatch';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL `ms_ranked_cache_restore_20261007`();
DROP PROCEDURE `ms_ranked_cache_restore_20261007`;

SELECT `Entry`, `Reference`, `Chance`, `GroupId`, `MinCount`, `MaxCount`
FROM `item_loot_template` WHERE `Entry` IN (1278059,1278064,1278073,1278082) ORDER BY `Entry`, `Item`;
SELECT `Entry`, COUNT(*) AS `Candidates`
FROM `reference_loot_template`
    WHERE `Entry` IN (9003801,9003802,9003803,9003804)
GROUP BY `Entry`;
DROP TEMPORARY TABLE `tmp_ms_ranked_candidate`;
